static (string,int) Ladder(string b,int n,int p){
    char defender=b[p],attacker=Other(defender);
    (bool,int) Read(string current,int depth,bool defending){
        if(depth>=40)return (defending,-1);
        Group g=GetGroup(current,n,p);
        SortedSet<int>candidates=new(g.Liberties);
        HashSet<int>seen=[];
        if(defending)foreach(int q in g.Stones)foreach(int t in Adjacent(q,n))if(current[t]==attacker&&!seen.Contains(t)){
            Group e=GetGroup(current,n,t);
            seen.UnionWith(e.Stones);
            if(e.Liberties.Count==1)candidates.UnionWith(e.Liberties);
        }
        foreach(int q in candidates){
            Placement next=Place(current,n,defending?defender:attacker,q);
            if(next.Reason!="")continue;
            bool success;
            if(defending){
                int count=GetGroup(next.Board,n,p).Liberties.Count;
                success=count>=3||(count==2&&!Read(next.Board,depth+1,false).Item1);
            }else success=!Read(next.Board,depth+1,true).Item1;
            if(success)return memo[key]=(true,q);
        }
        return memo[key]=(false,-1);
